    // La campanita que suena (v0.95.0): mientras haya
    // avisos sin leer, el icono se sacude en ciclos
    // (suena ~1 s y descansa ~2 s).
    private boolean bellRinging;
    private long bellRingStart;
    private final android.os.Handler bellHandler =
            new android.os.Handler(
                    android.os.Looper.getMainLooper());
    private final Runnable bellTick = new Runnable() {
        @Override
        public void run() {
            if (!bellRinging || bellIconView == null) return;
            long el = android.os.SystemClock.uptimeMillis()
                    - bellRingStart;
            long cycle = el % 3000L;
            if (cycle < 1000L) {
                double ph = cycle / 1000.0 * Math.PI * 5.0;
                double env = 1.0 - cycle / 1000.0 * 0.35;
                bellIconView.setRotation(
                        (float) (13.0 * Math.sin(ph) * env));
            } else {
                bellIconView.setRotation(0f);
            }
            bellHandler.postDelayed(this, 16);
        }
    };

    private void setBellRinging(boolean on) {
        if (on == bellRinging) return;
        bellRinging = on;
        bellHandler.removeCallbacks(bellTick);
        if (on) {
            bellRingStart = android.os.SystemClock
                    .uptimeMillis();
            bellHandler.post(bellTick);
        } else if (bellIconView != null) {
            bellIconView.setRotation(0f);
        }
    }
