    // Token para el que ya se intentó la renovación
    // silenciosa al vencer (v0.71.0): un intento por token.
    private long renewTriedForExp = -1;

    private final Runnable countdownTick = new Runnable() {
        @Override
        public void run() {
            if (state != State.MICUENTA) return;
            long remaining = sessionExpSec - nowSec();
            if (remaining <= 0) {
                // Al vencer ya NO se rebota al login
                // (v0.71.0): se intenta renovar en
                // silencio una vez; si sale, la hoja se
                // repinta con el token nuevo.
                if (renewTriedForExp != sessionExpSec
                        && sessionExpSec > 0) {
                    renewTriedForExp = sessionExpSec;
                    txtCountdown.setText("Renovando la sesión…");
                    exec.execute(() -> {
                        boolean ok = new ApiClient(store)
                                .refreshNow();
                        handler.post(() -> {
                            if (ok && state == State.MICUENTA) {
                                showSessionFromStore();
                            } else if (state == State.MICUENTA
                                    && txtCountdown != null) {
                                txtCountdown.setText(
                                        "El token venció — la "
                                        + "sesión se renueva "
                                        + "sola al cargar datos");
                            }
                        });
                    });
                } else {
                    txtCountdown.setText("El token venció — la "
                            + "sesión se renueva sola al "
                            + "cargar datos");
                }
                return;
            }
            txtCountdown.setText("El token de acceso expira en " + fmtDuration(remaining));
            handler.postDelayed(this, 1000);
        }
    };

