    private double autoFloor() {
        return Math.max(minAutoCup(), autoFloorRate());
    }

    private double autoFloorRate() {
        double priceUsdt = priceUsdt();
        long lastRateCup = lastRateCup();
        if (priceUsdt <= 0.0d || lastRateCup <= 0) {
            return 0.0d;
        }
        return priceUsdt * lastRateCup * (1.0d - (autoTolPct() / 100.0d));
    }

    private int autoMonthsFor(double d) {
        double priceUsdt = priceUsdt();
        long lastRateCup = lastRateCup();
        if (priceUsdt <= 0.0d || lastRateCup <= 0) {
            return 1;
        }
        double d2 = priceUsdt * lastRateCup;
        double autoTolPct = autoTolPct() / 100.0d;
        for (int i = 3; i >= 2; i--) {
            double d3 = i * d2;
            if (d >= (1.0d - autoTolPct) * d3 && d <= d3 * (1.0d + autoTolPct)) {
                return i;
            }
        }
        return d >= (d2 * 2.0d) * (1.0d - autoTolPct) ? -1 : 1;
    }

