    private void openLinkSheet(JSONObject jSONObject, VpnGroup vpnGroup) {
        if (this.vpnGroups == null) {
            if (contactsPermissionGranted()) {
                ensureContacts();
                this.pendingLinkUser = jSONObject;
                this.pendingLinkPreset = vpnGroup;
            } else {
                this.vpnGroups = new HashMap();
                this.contactsLoadedMs = 0L;
            }
        }
        LinkForm linkForm = new LinkForm();
        if (jSONObject != null) {
            Object opt = jSONObject.opt("id");
            linkForm.userId = opt instanceof Number ? ((Number) opt).longValue() : -1L;
            linkForm.userName = DataHelp.fieldStr(jSONObject, "username");
            JSONObject linkForUser = linkForUser(linkForm.userId);
            if (linkForUser != null) {
                restoreLinkInto(linkForm, linkForUser);
            } else {
                VpnGroup groupForAccount = groupForAccount(jSONObject);
                if (groupForAccount != null) {
                    linkForm.waGroup = groupForAccount.base;
                    linkForm.mainNum = defaultMain(groupForAccount);
                }
            }
        }
        if (vpnGroup != null) {
            linkForm.waGroup = vpnGroup.base;
            linkForm.mainNum = defaultMain(vpnGroup);
        }
        openLinkForm(linkForm);
    }

