    private int paidGroupKey(HomeStats.PayEntry payEntry) {
        long paidArrivalMs = paidArrivalMs(payEntry);
        if (paidArrivalMs <= 0) {
            return (payEntry.year * 100) + payEntry.month;
        }
        Calendar havanaCal = havanaCal(paidArrivalMs);
        return (havanaCal.get(1) * 100) + havanaCal.get(2) + 1;
    }

    private boolean paidInWindow(HomeStats.PayEntry payEntry) {
        int paidGroupKey = paidGroupKey(payEntry);
        Calendar havanaCal = havanaCal(System.currentTimeMillis());
        for (int i = 0; i < 4; i++) {
            if (paidGroupKey == (havanaCal.get(1) * 100) + havanaCal.get(2) + 1) {
                return true;
            }
            havanaCal.add(2, -1);
        }
        return false;
    }

