    private String vpnBaseKey(String str) {
        if (str == null) {
            return null;
        }
        String lowerCase = str.replaceAll("\\([^)]*\\)", " ").trim().toLowerCase(Locale.ROOT);
        try {
            lowerCase = Normalizer.normalize(lowerCase, Normalizer.Form.NFD).replaceAll("\\p{M}", "");
        } catch (Exception e) {
        }
        String[] split = lowerCase.replaceAll("[^a-z0-9 ]", " ").replaceAll("\\s+", " ").trim().split(" ");
        int i = 0;
        while (true) {
            if (i >= split.length) {
                i = -1;
                break;
            }
            if ("vpn".equals(split[i])) {
                break;
            }
            i++;
        }
        if (i <= 0) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        for (int i2 = 0; i2 < i; i2++) {
            if (sb.length() > 0) {
                sb.append(" ");
            }
            sb.append(split[i2]);
        }
        return sb.toString();
    }

    private String vpnDisplayBase(String str) {
        if (str == null) {
            return null;
        }
        String replaceAll = str.replaceAll("\\([^)]*\\)", " ");
        String lowerCase = replaceAll.toLowerCase(Locale.ROOT);
        int indexOf = lowerCase.indexOf(" vpn");
        if (indexOf < 0) {
            if (!lowerCase.trim().endsWith("vpn")) {
                return null;
            }
            indexOf = replaceAll.trim().length() - 3;
        }
        String trim = replaceAll.substring(0, Math.min(indexOf, replaceAll.length())).trim();
        if (trim.isEmpty()) {
            return null;
        }
        return trim;
    }

