    /** own = túnel PROPIO (Mi cuenta, v0.74.0): la ruta
     *  va SIN el alcance de clientes (?personal=false
     *  es solo para los de clientes) y al aplicar se
     *  refresca su lista. */
    private void openRegenerate(final JSONObject t,
            final boolean own) {
        final long id = requireId(t);
        if (id < 0) return;
        openAct("Regenerar túnel");
        actTunnel = t;
        actClientRow(Ico.KEY, DataHelp.fieldStr(t, "name"));
        actText("Se generan claves y una configuración nuevas, y la "
                + "configuración anterior deja de funcionar. El cliente "
                + "tendrá que importar la configuración nueva en su app "
                + "WireGuard.", TEXT2, 12);
        // Sensible (v0.36.0): regenerar claves corta la
        // conexión del cliente — nunca se encola.
        setActPrimary("Regenerar", () -> {
            nextWriteNoQueue = true;
            if (own) {
                pendingAfterWrite = () -> {
                    ownTunnels = null;
                    if (state == State.MICUENTA) {
                        renderMiCuentaView();
                        loadOwnTunnels();
                    }
                };
            }
            doWrite("Escritura — regenerar túnel", "POST",
                    PanelConfig.tunnelUrl(id)
                            + (own ? "regenerate/"
                                    : PanelConfig.REGENERATE_SUFFIX),
                    "{}", "Túnel regenerado",
                    DataHelp.fieldStr(t, "name"));
        });
    }

