    /** Escritura de nota (túnel o cuenta): texto normal, o
     *  NULA cuando notes == null (borrar la nota). */
    private void writeNote(final String diagLabel, final String url,
                           String ownerLabel, String notes,
                           String successMsg) {
        String body;
        try {
            JSONObject o = new JSONObject();
            o.put("notes", notes != null ? notes : JSONObject.NULL);
            body = o.toString();
        } catch (Exception e) {
            actShowError("No se pudo construir la petición.");
            return;
        }
        doWrite(diagLabel, "PATCH", url, body, successMsg, ownerLabel);
    }

    private void openNoteEditor(String title, String ownerLabel, String current,
                                final String diagLabel, final String url) {
        openNoteEditor(title, ownerLabel, current, diagLabel, url, true);
    }

    private void openNoteEditor(String title, String ownerLabel, String current,
                                final String diagLabel, final String url,
                                boolean explain) {
        openAct(title);
        final EditText input = makeTextInput("Escribe la nota aquí…", true);
        input.setText(current != null ? current : "");
        actAddField("Nota", input);
        // El texto de explicación SALE del
        // modal de notas del TÚNEL (v1.5.14,
        // su orden); la nota de cuenta lo
        // conserva.
        if (explain) {
            actText("No es una nota local de la app: es el comentario en la "
                    + "web, sincronizado en los dos sentidos. Lo que guardes "
                    + "aquí se ve en el panel, y lo que cambies en el panel "
                    + "se ve aquí.", TEXT2, 12);
        }
        actCancelBtn.setText("Cerrar");
        final boolean hasNote = current != null
                && !current.trim().isEmpty();
        // Eliminar la nota (v0.34.0; SIN botón propio desde la
        // v0.35.0, su orden: «sin tantos botones»): guardar el
        // texto VACÍO manda la nota NULA y el panel la borra
        // (confirmado en vivo por él; el «notes":""» antiguo
        // el panel lo ignoraba y la nota no se podía quitar).
        setActPrimary("Guardar nota", () -> {
            String txt = input.getText() != null
                    ? input.getText().toString() : "";
            if (txt.trim().isEmpty()) {
                if (!hasNote) {
                    closeAct();
                    return;
                }
                writeNote(diagLabel, url, ownerLabel, null,
                        "Nota eliminada");
                return;
            }
            writeNote(diagLabel, url, ownerLabel, txt, "Nota guardada");
        });
    }

